import sys

MOD = 998244353
G = 3

def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for i in range(0, n, length):
            w = 1
            end = i + half
            for k in range(i, end):
                u = a[k]
                v = a[k + half] * w % MOD
                a[k] = (u + v) % MOD
                a[k + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD

def convolution(a, b):
    if not a or not b:
        return []
    if min(len(a), len(b)) <= 60:
        res = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    need = len(a) + len(b) - 1
    z = 1
    while z < need:
        z <<= 1
    fa = a + [0] * (z - len(a))
    fb = b + [0] * (z - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(z):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:need]

def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()

    fact = [1] * (N + 1)
    invfact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # t[b] = number of W's before the next B after the b-th B.
    # For b=N, only internal cuts matter, so t[N]=N-1.
    t = [0] * (N + 1)
    bcnt = 0
    wcnt = 0
    for ch in S:
        if ch == 'W':
            wcnt += 1
        else:
            if bcnt > 0:
                t[bcnt] = wcnt
            bcnt += 1
    t[N] = N - 1

    valid = [False] * (N + 1)
    for b in range(1, N + 1):
        valid[b] = (t[b] >= b)

    f = [0] * (N + 1)
    acc = [0] * (N + 1)

    sys.setrecursionlimit(1 << 20)

    def solve(l, r):
        if l == r:
            if valid[l]:
                x = t[l]
                base = fact[x] * invfact[x - l] % MOD
                f[l] = (base - acc[l] * invfact[x - l]) % MOD
            return

        m = (l + r) >> 1
        solve(l, m)

        targets = [i for i in range(m + 1, r + 1) if valid[i]]
        if targets:
            max_x = max(t[i] for i in targets)

            src = [f[j] for j in range(l, m + 1)]
            ker = fact[:max_x - l + 1]
            conv = convolution(src, ker)

            for i in targets:
                idx = t[i] - l
                if idx < len(conv):
                    acc[i] = (acc[i] + conv[idx]) % MOD

        solve(m + 1, r)

    solve(1, N)

    bad = 0
    for b in range(1, N + 1):
        bad = (bad + f[b] * fact[N - b]) % MOD

    print((fact[N] - bad) % MOD)

if __name__ == "__main__":
    main()

import sys

def compatible(a1, b1, d1, a2, b2, d2):
    # d = 1: moving right, base is lower than internal points
    # d = -1: moving left, base is higher than internal points

    coords = {a1, b1, a2, b2}

    lo = max(a1, a2)
    hi = min(b1, b2)
    if lo + 1 < hi:
        coords.add(lo + 1)

    coords = sorted(coords)
    idx = {x: i for i, x in enumerate(coords)}
    n = len(coords)

    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(x, y):
        x = find(x)
        y = find(y)
        if x != y:
            parent[y] = x

    unite(idx[a1], idx[b1])
    unite(idx[a2], idx[b2])

    edges_raw = []

    def add_constraints(a, b, d):
        base_a = idx[a]
        base_b = idx[b]
        for x in coords:
            if a < x < b:
                xi = idx[x]
                if d == 1:
                    edges_raw.append((base_a, xi))
                else:
                    edges_raw.append((xi, base_a))

    add_constraints(a1, b1, d1)
    add_constraints(a2, b2, d2)

    comp_id = {}
    cid = 0
    for i in range(n):
        r = find(i)
        if r not in comp_id:
            comp_id[r] = cid
            cid += 1

    g = [[] for _ in range(cid)]
    indeg = [0] * cid

    for u, v in edges_raw:
        cu = comp_id[find(u)]
        cv = comp_id[find(v)]
        if cu == cv:
            return False
        g[cu].append(cv)
        indeg[cv] += 1

    stack = [i for i in range(cid) if indeg[i] == 0]
    seen = 0
    while stack:
        v = stack.pop()
        seen += 1
        for to in g[v]:
            indeg[to] -= 1
            if indeg[to] == 0:
                stack.append(to)

    return seen == cid


def main():
    input = sys.stdin.readline
    N, M, Q = map(int, input().split())

    intervals = []
    for _ in range(M):
        s, t = map(int, input().split())
        if s < t:
            intervals.append((s - 1, t - 1, 1))
        else:
            intervals.append((t - 1, s - 1, -1))

    # bad[r] = maximum l < r such that persons l and r cannot coexist.
    # The condition is hereditary, so each query is answered by checking
    # whether any conflicting pair lies completely inside the query range.
    bad = [-1] * M

    for r in range(M):
        a2, b2, d2 = intervals[r]
        mx = -1
        for l in range(r):
            a1, b1, d1 = intervals[l]
            if not compatible(a1, b1, d1, a2, b2, d2):
                mx = l
        bad[r] = mx

    segsize = 1
    while segsize < M:
        segsize <<= 1

    seg = [-1] * (2 * segsize)
    for i, x in enumerate(bad):
        seg[segsize + i] = x
    for i in range(segsize - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def range_max(l, r):
        l += segsize
        r += segsize
        ans = -1
        while l <= r:
            if l & 1:
                ans = max(ans, seg[l])
                l += 1
            if not (r & 1):
                ans = max(ans, seg[r])
                r -= 1
            l >>= 1
            r >>= 1
        return ans

    out = []
    for _ in range(Q):
        l, r = map(int, input().split())
        l -= 1
        r -= 1
        if range_max(l, r) >= l:
            out.append("No")
        else:
            out.append("Yes")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

