from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def required_steps_upto(n: int) -> int:
            if n <= 0:
                return 0

            total = 0
            start = 1
            steps = 1

            while start <= n:
                end = start * 4 - 1
                total += (min(n, end) - start + 1) * steps
                start *= 4
                steps += 1

            return total

        answer = 0

        for l, r in queries:
            total_steps = required_steps_upto(r) - required_steps_upto(l - 1)
            answer += (total_steps + 1) // 2

        return answer

