                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    cnt[color[to]] += 1
                    stack.append(to)

        size = cnt[0] + cnt[1]
        if size % 2 == 1:
            odd_components += 1
        else:
            even_component_color0_parity ^= (cnt[0] & 1)

    if N % 2 == 1:
        winner = "Aoki" if M % 2 == 1 else "Takahashi"
    else:
        if odd_components % 4 == 2:
            winner = "Aoki"
        elif odd_components % 4 == 0 and odd_components > 0:
            winner = "Takahashi"
        else:
            final_edge_parity = even_component_color0_parity
            winner = "Aoki" if final_edge_parity != (M & 1) else "Takahashi"

