from collections import defaultdict
from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        digit_info = {
            1: (1, 0, 0, 0, 0),
            2: (2, 1, 0, 0, 0),
            3: (3, 0, 1, 0, 0),
            4: (4, 2, 0, 0, 0),
            5: (5, 0, 0, 1, 0),
            6: (6, 1, 1, 0, 0),
            7: (7, 0, 0, 0, 1),
            8: (8, 3, 0, 0, 0),
            9: (9, 0, 2, 0, 0),
        }

        @lru_cache(None)
        def required_factors(s: int):
            x = s
            need2 = need3 = need5 = need7 = 0

            while x % 2 == 0:
                x //= 2
                need2 += 1
            while x % 3 == 0:
                x //= 3
                need3 += 1
            while x % 5 == 0:
                x //= 5
                need5 += 1
            while x % 7 == 0:
                x //= 7
                need7 += 1

            if x != 1:
                return None
            return need2, need3, need5, need7

        def is_beautiful_state(state):
            s, a, b, c, d = state
            req = required_factors(s)
            if req is None:
                return False
            return a >= req[0] and b >= req[1] and c >= req[2] and d >= req[3]

        max_len = 9

        # dp_by_len[k] stores all states for k-digit positive numbers without zero digits.
        dp_by_len = [None] * (max_len + 1)
        dp_by_len[0] = {(0, 0, 0, 0, 0): 1}

        valid_by_len = [0] * (max_len + 1)

        for length in range(1, max_len + 1):
            prev = dp_by_len[length - 1]
            cur = defaultdict(int)

            for (s, a, b, c, d), cnt in prev.items():
                for digit in range(1, 10):
                    ds, da, db, dc, dd = digit_info[digit]
                    cur[(s + ds, a + da, b + db, c + dc, d + dd)] += cnt

            dp_by_len[length] = dict(cur)
            valid_by_len[length] = sum(
                cnt for state, cnt in cur.items() if is_beautiful_state(state)
            )

        pow9 = [1] * (max_len + 1)
        for i in range(1, max_len + 1):
            pow9[i] = pow9[i - 1] * 9

        def count_no_zero_numbers(x: int) -> int:
            if x <= 0:
                return 0

            digits = list(map(int, str(x)))
            n = len(digits)

            total = sum(pow9[length] for length in range(1, n))

            for i, digit in enumerate(digits):
                smaller_nonzero = max(0, digit - 1)
                total += smaller_nonzero * pow9[n - i - 1]

                if digit == 0:
                    return total

            return total + 1

        def count_beautiful_without_zero(x: int) -> int:
            if x <= 0:
                return 0

            digits = list(map(int, str(x)))
            n = len(digits)

            result = sum(valid_by_len[length] for length in range(1, n))

            loose = {}
            tight_state = (0, 0, 0, 0, 0)
            tight_alive = True

            for limit in digits:
                new_loose = defaultdict(int)

                # Extend prefixes already smaller than x.
                for (s, a, b, c, d), cnt in loose.items():
                    for digit in range(1, 10):
                        ds, da, db, dc, dd = digit_info[digit]
                        new_loose[(s + ds, a + da, b + db, c + dc, d + dd)] += cnt

                # Make the current prefix smaller than x at this digit.
                if tight_alive:
                    s, a, b, c, d = tight_state
                    for digit in range(1, limit):
                        ds, da, db, dc, dd = digit_info[digit]
                        new_loose[(s + ds, a + da, b + db, c + dc, d + dd)] += 1

                    # Continue matching x exactly.
                    if limit == 0:
                        tight_alive = False
                    else:
                        ds, da, db, dc, dd = digit_info[limit]
                        tight_state = (s + ds, a + da, b + db, c + dc, d + dd)

                loose = dict(new_loose)

            for state, cnt in loose.items():
                if is_beautiful_state(state):
                    result += cnt

            if tight_alive and is_beautiful_state(tight_state):
                result += 1

            return result

        def count_beautiful(x: int) -> int:
            if x <= 0:
                return 0

            no_zero_count = count_no_zero_numbers(x)
            zero_digit_count = x - no_zero_count

            return zero_digit_count + count_beautiful_without_zero(x)

        return count_beautiful(r) - count_beautiful(l - 1)

