from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def max_flow(self, s, t):
        flow = 0
        INF = 10 ** 18

        while True:
            level = [-1] * self.n
            level[s] = 0
            q = deque([s])

            while q:
                v = q.popleft()
                for to, cap, _ in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                return flow

            it = [0] * self.n

            def dfs(v, f):
                if v == t:
                    return f

                while it[v] < len(self.g[v]):
                    idx = it[v]
                    to, cap, rev = self.g[v][idx]

                    if cap > 0 and level[v] < level[to]:
                        pushed = dfs(to, min(f, cap))
                        if pushed:
                            self.g[v][idx][1] -= pushed
                            self.g[to][rev][1] += pushed
                            return pushed

                    it[v] += 1

                return 0

            while True:
                pushed = dfs(s, INF)
                if pushed == 0:
                    break
                flow += pushed


def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(M)]

    INF = 10 ** 9

    def feasible(D):
        if D == 0:
            return True

        def node(v, level):
            return (v - 1) * D + (level - 1)

        total_nodes = N * D + 2
        source = N * D
        sink = source + 1
        mf = Dinic(total_nodes)

        for v in range(1, N + 1):
            for level in range(2, D + 1):
                mf.add_edge(node(v, level), node(v, level - 1), INF)

        for level in range(1, D + 1):
            mf.add_edge(node(1, level), sink, INF)
            mf.add_edge(source, node(N, level), INF)

        for u, v in edges:
            for level in range(1, D + 1):
                mf.add_edge(node(v, level), node(u, level), 1)
            for level in range(2, D + 1):
                mf.add_edge(node(v, level), node(u, level - 1), INF)

        return mf.max_flow(source, sink) <= K

    low = 0
    high = N

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)

