    main()

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    V = N * K

    if K == 1:
        print("Yes")
        return

    graph = [[] for _ in range(V)]
    idx = 2
    for _ in range(V - 1):
        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2
        graph[u].append(v)
        graph[v].append(u)

    parent = [-1] * V
    order = [0]
    parent[0] = -2

    for v in order:
        for to in graph[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            order.append(to)

    remain = [0] * V
    possible = True

    for v in reversed(order):
        active = []

        for to in graph[v]:
            if parent[to] == v:
                if remain[to] == -1:
                    possible = False
                    break
                if remain[to] > 0:
                    active.append(remain[to])

        if not possible:
            break

        if len(active) == 0:
            remain[v] = 1
        elif len(active) == 1:
            length = active[0] + 1
            remain[v] = 0 if length == K else length
        elif len(active) == 2:
            if active[0] + active[1] + 1 == K:
                remain[v] = 0
            else:
                remain[v] = -1
                possible = False
                break
        else:
            remain[v] = -1
            possible = False
            break

    if possible and remain[0] == 0:
        print("Yes")
    else:
        print("No")

