    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    p = data[1:]

    bit = [0] * (n + 1)

    def add(i):
        while i <= n:
            bit[i] += 1
            i += i & -i

    def prefix_sum(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = 0

    for j, x in enumerate(p, start=1):
        greater_before = (j - 1) - prefix_sum(x)
        if greater_before:
            ans += greater_before * (2 * j - greater_before - 1) // 2
        add(x)

    print(ans)

