import sys

def normal_form(s, x, y):
    parts = []
    pending_zero_blocks = 0  # blocks of 0^X
    pending_one_blocks = 0   # blocks of 1^Y

    def flush():
        nonlocal pending_zero_blocks, pending_one_blocks
        if pending_zero_blocks:
            parts.append('0' * (pending_zero_blocks * x))
            pending_zero_blocks = 0
        if pending_one_blocks:
            parts.append('1' * (pending_one_blocks * y))
            pending_one_blocks = 0

    n = len(s)
    i = 0

    while i < n:
        j = i
        c = s[i]
        while j < n and s[j] == c:
            j += 1

        length = j - i

        if c == '0':
            q, r = divmod(length, x)
            pending_zero_blocks += q
            if r:
                flush()
                parts.append('0' * r)
        else:
            q, r = divmod(length, y)
            if r:
                flush()
                parts.append('1' * r)
            pending_one_blocks += q

        i = j

    flush()
    return ''.join(parts)

def main():
    input = sys.stdin.readline
    n, x, y = map(int, input().split())
    s = input().strip()
    t = input().strip()

    if normal_form(s, x, y) == normal_form(t, x, y):
        print("Yes")
    else:
        print("No")

