from typing import List


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            left, right = (a, b) if a < b else (b, a)
            buckets[right].append((left, idx))

        max_left = 0
        second_max_left = 0
        max_count = 0
        max_pair_id = -1

        total_valid = 0
        gains = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for left, pair_id in buckets[right]:
                if left > max_left:
                    second_max_left = max_left
                    max_left = left
                    max_count = 1
                    max_pair_id = pair_id
                elif left == max_left:
                    max_count += 1
                else:
                    second_max_left = max(second_max_left, left)

            total_valid += right - max_left

            if max_count == 1:
                gains[max_pair_id] += max_left - second_max_left

        return total_valid + max(gains)

