        graph[y].append((x, z))

    value = [-1] * N

    for start in range(N):
        if value[start] != -1:
            continue

        value[start] = 0
        stack = [start]
        component = []

        while stack:
            v = stack.pop()
            component.append(v)

            for to, z in graph[v]:
                expected = value[v] ^ z
                if value[to] == -1:
                    value[to] = expected
                    stack.append(to)
                elif value[to] != expected:
                    print(-1)
                    return

        size = len(component)
        shift = 0

        for bit in range(30):
            ones = 0
            mask = 1 << bit
            for v in component:
                if value[v] & mask:
                    ones += 1
            if ones > size - ones:
                shift |= mask

        for v in component:
            value[v] ^= shift

    print(*value)

