class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        length = n + m - 1

        # Force characters required by all 'T' positions.
        fixed = [-1] * length
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    ch = ord(str2[j]) - 97
                    if fixed[pos] != -1 and fixed[pos] != ch:
                        return ""
                    fixed[pos] = ch

        # KMP prefix function.
        pattern = [ord(c) - 97 for c in str2]
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j

        # Automaton transitions for states 0..m-1.
        # State represents how many prefix characters currently match.
        trans = [[0] * m for _ in range(26)]
        for state in range(m):
            for ch in range(26):
                j = state
                while j > 0 and pattern[j] != ch:
                    j = pi[j - 1]
                if pattern[j] == ch:
                    j += 1
                if j == m:
                    j = pi[m - 1]
                trans[ch][state] = j

        all_states = (1 << m) - 1
        possible = [0] * (length + 1)
        possible[length] = all_states

        last_char = pattern[-1]

        # Backward DP:
        # possible[pos] is the set of KMP states from which the suffix
        # beginning at pos can be completed validly.
        for pos in range(length - 1, -1, -1):
            next_mask = possible[pos + 1]
            start = pos - m + 1
            forbidden_match = 0 <= start < n and str1[start] == 'F'

            if fixed[pos] != -1:
                ch = fixed[pos]
                mask = 0
                transitions = trans[ch]

                for state in range(m):
                    # A full match occurs exactly from state m-1 using pattern[-1].
                    if forbidden_match and state == m - 1 and ch == last_char:
                        continue
                    if (next_mask >> transitions[state]) & 1:
                        mask |= 1 << state

                possible[pos] = mask
            else:
                # If state 0 is viable after this position, every state is viable:
                # choose any character different from pattern[0], which always
                # transitions to state 0.
                if next_mask & 1:
                    possible[pos] = all_states
                    continue

                mask = 0
                for state in range(m):
                    for ch in range(26):
                        if forbidden_match and state == m - 1 and ch == last_char:
                            continue
                        nxt = trans[ch][state]
                        if (next_mask >> nxt) & 1:
                            mask |= 1 << state
                            break

                possible[pos] = mask

        if possible[0] == 0:
            return ""

        # Construct lexicographically smallest valid string.
        result = []
        state = 0

        for pos in range(length):
            start = pos - m + 1
            forbidden_match = 0 <= start < n and str1[start] == 'F'

            candidates = [fixed[pos]] if fixed[pos] != -1 else range(26)

            chosen = -1
            for ch in candidates:
                if forbidden_match and state == m - 1 and ch == last_char:
                    continue

                nxt = trans[ch][state]
                if (possible[pos + 1] >> nxt) & 1:
                    chosen = ch
                    state = nxt
                    break

            if chosen == -1:
                return ""

            result.append(chr(chosen + 97))

        return "".join(result)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        LIMIT = 10**15

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(LIMIT, fact[i - 1] * i)

        def count_completions(odd_left: int, even_left: int, need_odd: bool) -> int:
            remaining = odd_left + even_left

            if need_odd:
                required_odd = (remaining + 1) // 2
                required_even = remaining // 2
            else:
                required_odd = remaining // 2
                required_even = (remaining + 1) // 2

            if odd_left != required_odd or even_left != required_even:
                return 0

            return min(LIMIT, fact[odd_left] * fact[even_left])

        odd_left = (n + 1) // 2
        even_left = n // 2
        used = [False] * (n + 1)
        answer = []

        for pos in range(n):
            for value in range(1, n + 1):
                if used[value]:
                    continue

                is_odd = (value % 2 == 1)
                next_odd_left = odd_left - (1 if is_odd else 0)
                next_even_left = even_left - (0 if is_odd else 1)

                # After choosing this value, the next required parity is opposite.
                ways = count_completions(
                    next_odd_left,
                    next_even_left,
                    need_odd=not is_odd
                )

                if k > ways:
                    k -= ways
                else:
                    answer.append(value)
                    used[value] = True
                    odd_left = next_odd_left
                    even_left = next_even_left
                    break
            else:
                return []

        return answer

import sys
from bisect import bisect_left, bisect_right

def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        n = int(data[idx])
        a_str = data[idx + 1]
        b_str = data[idx + 2]
        idx += 3

        a = [i for i, ch in enumerate(a_str) if ch == 49]
        b = [i for i, ch in enumerate(b_str) if ch == 49]

        p = len(a)
        m = len(b)

        if p < m:
            out.append("-1")
            continue

        if m == 1:
            ans = max(abs(a[0] - b[0]), abs(a[-1] - b[0]))
            out.append(str(ans))
            continue

        gaps_a = [a[i + 1] - a[i] for i in range(p - 1)]
        gaps_b = [b[i + 1] - b[i] for i in range(m - 1)]

        size = 1
        while size < p - 1:
            size <<= 1

        seg = [0] * (2 * size)
        seg[size:size + p - 1] = gaps_a
        for i in range(size - 1, 0, -1):
            left = seg[i << 1]
            right = seg[i << 1 | 1]
            seg[i] = left if left >= right else right

        def first_gap_at_least(start, value):
            """Smallest gap index >= start whose value is at least value."""
            if start >= p - 1 or seg[1] < value:
                return -1
            if gaps_a[start] >= value:
                return start

            l = start + size
            r = (p - 2) + size
            left_nodes = []
            right_nodes = []

            while l <= r:
                if l & 1:
                    if seg[l] >= value:
                        left_nodes.append(l)
                    l += 1
                if not (r & 1):
                    if seg[r] >= value:
                        right_nodes.append(r)
                    r -= 1
                l >>= 1
                r >>= 1

            node = -1
            for x in left_nodes:
                if seg[x] >= value:
                    node = x
                    break

            if node == -1:
                for x in reversed(right_nodes):
                    if seg[x] >= value:
                        node = x
                        break

            if node == -1:
                return -1

            while node < size:
                left = node << 1
                if seg[left] >= value:
                    node = left
                else:
                    node = left | 1

            res = node - size
            return res if res < p - 1 else -1

        def feasible(k):
            # The first piece must be assignable to the first target square.
            if a[0] < b[0] - k:
                return False

            prev_end = -1

            for j in range(m - 1):
                # Last possible initial piece that can map to b[j].
                right = bisect_right(a, b[j] + k) - 1

                # First initial piece that can map to b[j+1].
                next_left = bisect_left(a, b[j + 1] - k)

                min_end = prev_end + 1
                needed = next_left - 1
                if needed > min_end:
                    min_end = needed

                if min_end > right or min_end >= p - 1:
                    return False

                gap_index = first_gap_at_least(min_end, gaps_b[j])
                if gap_index == -1 or gap_index > right:
                    return False

                prev_end = gap_index

            # All remaining pieces must map to the final target square.
            if prev_end + 1 >= p:
                return False
            if a[prev_end + 1] < b[-1] - k:
                return False
            if a[-1] > b[-1] + k:
                return False

            return True

        if not feasible(n):
            out.append("-1")
            continue

        lo = -1
        hi = n
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid

        out.append(str(hi))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

