class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter_positions = []

        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 3 * side - x
            else:
                t = 4 * side - y
            perimeter_positions.append(t)

        perimeter_positions.sort()
        n = len(perimeter_positions)
        total_perimeter = 4 * side
        circular_positions = perimeter_positions + [
            x + total_perimeter for x in perimeter_positions
        ]
        m = 2 * n

        def can_select(dist: int) -> bool:
            if dist == 0:
                return True

            nxt = [m] * (m + 1)
            j = 0

            for i in range(m):
                if j <= i:
                    j = i + 1

                target = circular_positions[i] + dist
                while j < m and circular_positions[j] < target:
                    j += 1

                nxt[i] = j

            for start in range(n):
                pos = start

                for _ in range(k - 1):
                    pos = nxt[pos]
                    if pos >= m:
                        break

                if pos < m and circular_positions[pos] <= circular_positions[start] + total_perimeter - dist:
                    return True

            return False

        low, high = 0, side

        while low < high:
            mid = (low + high + 1) // 2
            if can_select(mid):
                low = mid
            else:
                high = mid - 1

        return low

