def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    m = n - 1

    adj = [[] for _ in range(n)]
    u = [0] * m
    v = [0] * m

    idx = 1
    for e in range(m):
        a = data[idx] - 1
        b = data[idx + 1] - 1
        idx += 2
        u[e] = a
        v[e] = b
        adj[a].append((b, e))
        adj[b].append((a, e))

    if n == 1:
        print(-1)
        return

    parent = [-2] * n
    parent_edge = [-1] * n
    parent[0] = -1
    order = []
    stack = [0]

    while stack:
        x = stack.pop()
        order.append(x)
        for y, e in adj[x]:
            if y == parent[x]:
                continue
            parent[y] = x
            parent_edge[y] = e
            stack.append(y)

    # msg[2*e]   = best value for direction u[e] -> v[e]
    # msg[2*e+1] = best value for direction v[e] -> u[e]
    msg = [0] * (2 * m)

    # Bottom-up: compute child -> parent messages.
    for x in reversed(order):
        if parent[x] == -1:
            continue

        best1 = best2 = best3 = 0
        cnt = 0

        for y, e in adj[x]:
            if e == parent_edge[x]:
                continue

            if u[e] == y:
                val = msg[2 * e]
            else:
                val = msg[2 * e + 1]

            cnt += 1
            if val > best1:
                best3 = best2
                best2 = best1
                best1 = val
            elif val > best2:
                best3 = best2
                best2 = val
            elif val > best3:
                best3 = val

        value = 1
        if cnt >= 3:
            value += best1 + best2 + best3

        e = parent_edge[x]
        if u[e] == x:
            msg[2 * e] = value
        else:
            msg[2 * e + 1] = value

    ans = -1

    # Top-down: compute all remaining directed messages and evaluate every root.
    for x in order:
        deg = len(adj[x])

        if deg < 4:
            for y, e in adj[x]:
                if u[e] == x:
                    msg[2 * e] = 1
                else:
                    msg[2 * e + 1] = 1
            continue

        best1 = best2 = best3 = best4 = 0

        for y, e in adj[x]:
            if u[e] == y:
                val = msg[2 * e]
            else:
                val = msg[2 * e + 1]

            if val > best1:
                best4 = best3
                best3 = best2
                best2 = best1
                best1 = val
            elif val > best2:
                best4 = best3
                best3 = best2
                best2 = val
            elif val > best3:
                best4 = best3
                best3 = val
            elif val > best4:
                best4 = val

        ans = max(ans, 1 + best1 + best2 + best3 + best4)
        top3sum = best1 + best2 + best3

        for y, e in adj[x]:
            if u[e] == y:
                incoming = msg[2 * e]
            else:
                incoming = msg[2 * e + 1]

            if incoming >= best3:
                value = 1 + top3sum - incoming + best4
            else:
                value = 1 + top3sum

            if u[e] == x:
                msg[2 * e] = value
            else:
                msg[2 * e + 1] = value

    print(ans)

