class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(pattern: str):
            if not pattern:
                return list(range(n + 1))

            m = len(pattern)
            pi = [0] * m
            j = 0

            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]

            return result

        occ_a = occurrences(a)
        occ_b = occurrences(b)
        occ_c = occurrences(c)

        la, lb, lc = len(a), len(b), len(c)

        best = float("inf")
        i = 0
        k = 0
        latest_a = -1

        for pos_b in occ_b:
            while i < len(occ_a) and occ_a[i] + la <= pos_b:
                latest_a = occ_a[i]
                i += 1

            if latest_a == -1:
                continue

            end_b = pos_b + lb
            while k < len(occ_c) and occ_c[k] < end_b:
                k += 1

            if k == len(occ_c):
                break

            best = min(best, occ_c[k] + lc - latest_a)

        return -1 if best == float("inf") else best

