import sys

MOD = 998244353

def solve():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    factors = {}

    for i, x in enumerate(A):
        d = 2
        while d * d <= x:
            if x % d == 0:
                cnt = 0
                while x % d == 0:
                    x //= d
                    cnt += 1
                if d not in factors:
                    factors[d] = [0] * (N - 1)
                factors[d][i] = cnt
            d += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (N - 1)
            factors[x][i] = 1

    answer = 1

    for p, exps in factors.items():
        total = sum(exps)

        pw = [1] * (total + 1)
        for i in range(1, total + 1):
            pw[i] = pw[i - 1] * p % MOD

        # dp0[h]: current valuation is h, and 0 has not appeared yet.
        # Only h >= 1 is possible here.
        # Initially, the starting valuation can be any positive h up to total.
        dp0 = [0] * (total + 1)
        for h in range(1, total + 1):
            dp0[h] = pw[h]

        # dp1[h]: current valuation is h, and 0 has appeared at least once.
        dp1 = [1]

        pref = 0
        rem = total

        for d in exps:
            new_pref = pref + d
            new_rem = rem - d

            ndp0 = [0] * (new_rem + 1)
            ndp1 = [0] * (new_pref + 1)

            if d == 0:
                for h in range(1, rem + 1):
                    v = dp0[h]
                    if v:
                        ndp0[h] = v * pw[h] % MOD

                for h in range(pref + 1):
                    v = dp1[h]
                    if v:
                        ndp1[h] = v * pw[h] % MOD
            else:
                # Transitions from paths that have not touched 0 yet.
                for h in range(1, rem + 1):
                    v = dp0[h]
                    if not v:
                        continue

                    up = h + d
                    if up <= new_rem:
                        val = v * pw[up] % MOD
                        z = ndp0[up] + val
                        if z >= MOD:
                            z -= MOD
                        ndp0[up] = z

                    down = h - d
                    if down == 0:
                        z = ndp1[0] + v
                        if z >= MOD:
                            z -= MOD
                        ndp1[0] = z
                    elif down > 0 and down <= new_rem:
                        val = v * pw[down] % MOD
                        z = ndp0[down] + val
                        if z >= MOD:
                            z -= MOD
                        ndp0[down] = z

                # Transitions from paths that have already touched 0.
                for h in range(pref + 1):
                    v = dp1[h]
                    if not v:
                        continue

                    up = h + d
                    val = v * pw[up] % MOD
                    z = ndp1[up] + val
                    if z >= MOD:
                        z -= MOD
                    ndp1[up] = z

                    down = h - d
                    if down >= 0:
                        val = v * pw[down] % MOD
                        z = ndp1[down] + val
                        if z >= MOD:
                            z -= MOD
                        ndp1[down] = z

            dp0 = ndp0
            dp1 = ndp1
            pref = new_pref
            rem = new_rem

        contribution = sum(dp1) % MOD
        answer = answer * contribution % MOD

    print(answer)

