class Solution:
    def countSubstrings(self, s: str) -> int:
        transitions = [
            None,
            [[0] for _ in range(10)],
        ]

        for d in range(2, 10):
            trans_for_digit = []
            for digit in range(10):
                trans_for_digit.append([(r * 10 + digit) % d for r in range(d)])
            transitions.append(trans_for_digit)

        dp = [None] + [[0] * d for d in range(1, 10)]
        answer = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for d in range(1, 10):
                old = dp[d]
                new = [0] * d

                if d == 1:
                    new[0] = old[0] + 1
                else:
                    trans = transitions[d][digit]
                    for r, count in enumerate(old):
                        if count:
                            new[trans[r]] += count
                    new[digit % d] += 1

                dp[d] = new

            if digit != 0:
                answer += dp[digit][0]

        return answer

