        while idx <= n:
            bit[idx] += value
            idx += idx & -idx

    def kth(k):
        idx = 0
        step = 1 << (n.bit_length() - 1)
        while step:
            nxt = idx + step
            if nxt <= n and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            step >>= 1
        return idx + 1

    ans = [0] * n

    for i in range(n, 0, -1):
        pos = kth(p[i - 1])
