MOD = 998244353

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    S = input().strip()

    present = sorted(set(S))
    symbols = [(ord(c) - 97, 1) for c in present]
    absent_count = 26 - len(present)

    initial = tuple([0] * (N + 1))

    states = [initial]
    state_id = {initial: 0}
    transitions = [None]

    dp = [1]

    for _ in range(M):
        next_dp = [0] * len(dp)
        current_count = len(dp)

        for sid in range(current_count):
            value = dp[sid]
            if value == 0:
                continue

            if transitions[sid] is None:
                row = states[sid]
                merged = {}

                for char_code, count in symbols:
                    new_row = [0] * (N + 1)
                    for j in range(1, N + 1):
                        best = row[j]
                        if new_row[j - 1] > best:
                            best = new_row[j - 1]
                        if ord(S[j - 1]) - 97 == char_code:
                            candidate = row[j - 1] + 1
                            if candidate > best:
                                best = candidate
                        new_row[j] = best

                    new_state = tuple(new_row)
                    if new_state not in state_id:
                        state_id[new_state] = len(states)
                        states.append(new_state)
                        transitions.append(None)
                    tid = state_id[new_state]
                    merged[tid] = merged.get(tid, 0) + count

                if absent_count:
                    merged[sid] = merged.get(sid, 0) + absent_count

                transitions[sid] = list(merged.items())

            for tid, count in transitions[sid]:
                while tid >= len(next_dp):
                    next_dp.append(0)
                next_dp[tid] = (next_dp[tid] + value * count) % MOD

        dp = next_dp

    ans = [0] * (N + 1)
    for sid, value in enumerate(dp):
        if value:
            ans[states[sid][-1]] = (ans[states[sid][-1]] + value) % MOD

    print(*ans)

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_subarrays(a: int, b: int) -> int:
            t = min(a, k)
            q = min(t, max(0, k + 1 - b))
            return q * b + (t - q) * (k + 1) - (q + 1 + t) * (t - q) // 2

        def contribution_for_maximum() -> int:
            left = [0] * n
            stack = []

            for i, x in enumerate(nums):
                while stack and nums[stack[-1]] <= x:
                    stack.pop()
                left[i] = i - (stack[-1] if stack else -1)
                stack.append(i)

            stack.clear()
            total = 0

            for i in range(n - 1, -1, -1):
                x = nums[i]
                while stack and nums[stack[-1]] < x:
                    stack.pop()
                right = (stack[-1] if stack else n) - i
                total += x * count_subarrays(left[i], right)
                stack.append(i)

            return total

        def contribution_for_minimum() -> int:
            left = [0] * n
            stack = []

            for i, x in enumerate(nums):
                while stack and nums[stack[-1]] >= x:
                    stack.pop()
                left[i] = i - (stack[-1] if stack else -1)
                stack.append(i)

            stack.clear()
            total = 0

            for i in range(n - 1, -1, -1):
                x = nums[i]
                while stack and nums[stack[-1]] > x:
                    stack.pop()
                right = (stack[-1] if stack else n) - i
                total += x * count_subarrays(left[i], right)
                stack.append(i)

            return total

        return contribution_for_maximum() + contribution_for_minimum()

import sys

def main():
    N, P = map(int, sys.stdin.readline().split())
    H = N // 2
    E = N * (N - 1) // 2

    fact = [1] * (N + 1)
    invfact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % P
    invfact[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % P

    small_comb = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        small_comb[i][0] = small_comb[i][i] = 1
        for j in range(1, i):
            small_comb[i][j] = (small_comb[i - 1][j - 1] + small_comb[i - 1][j]) % P

    # coeff[k][j] is the coefficient of y^(a*j) in
    # ((y^a - 1)^k) / k!
    coeff = [[] for _ in range(N + 1)]
    for k in range(1, N + 1):
        cur = []
        for j in range(k + 1):
            v = small_comb[k][j] * invfact[k] % P
            if (k - j) & 1:
                v = (-v) % P
            cur.append(v)
        coeff[k] = cur

    # dp[t]: dictionary
    # key = ((even_count * 31 + last_layer_size) * 2 + parity_of_last_layer)
    # value = polynomial in y, where y = 1 + x
    dp = [None] * (N + 1)
    dp[1] = {(1 * 31 + 1) * 2: [1]}  # root alone, even layer

    for t in range(1, N):
        curdp = dp[t]
        if not curdp:
            continue

        for key, poly in curdp.items():
            parity = key & 1
            z = key >> 1
            last = z % 31
            even_count = z // 31

            next_parity = parity ^ 1

            max_k = N - t
            if next_parity == 0:
                max_k = min(max_k, H - even_count)
            else:
                max_k = min(max_k, H - (t - even_count))

            if max_k <= 0:
                continue

            plen = len(poly)

            for k in range(1, max_k + 1):
                new_t = t + k
                new_even = even_count + (k if next_parity == 0 else 0)

                new_key = ((new_even * 31 + k) * 2 + next_parity)
                target_dict = dp[new_t]
                if target_dict is None:
                    target_dict = {}
                    dp[new_t] = target_dict

                base = k * (k - 1) // 2
                highest = base + last * k
                needed_len = plen + highest

                out = target_dict.get(new_key)
                if out is None:
                    out = [0] * needed_len
                    target_dict[new_key] = out
                elif len(out) < needed_len:
                    out.extend([0] * (needed_len - len(out)))

                ck = coeff[k]

                for j in range(k + 1):
                    mul = ck[j]
                    if mul == 0:
                        continue
                    shift = base + last * j
                    end = shift + plen

                    if mul == 1:
                        for idx in range(plen):
                            v = poly[idx]
                            if v:
                                pos = shift + idx
                                nv = out[pos] + v
                                if nv >= P:
                                    nv -= P
                                out[pos] = nv
                    else:
                        for idx in range(plen):
                            v = poly[idx]
                            if v:
                                add = v * mul % P
                                pos = shift + idx
                                nv = out[pos] + add
                                if nv >= P:
                                    nv -= P
                                out[pos] = nv

        dp[t] = None

    F = [0] * (E + 1)
    final_dict = dp[N]
    if final_dict:
        for key, poly in final_dict.items():
            z = key >> 1
            even_count = z // 31
            if even_count != H:
                continue
            for i, v in enumerate(poly):
                if v:
                    F[i] += v
                    if F[i] >= P:
                        F[i] -= P

    multiplier = fact[N - 1]
    for i in range(E + 1):
        F[i] = F[i] * multiplier % P

    # Convert from polynomial in y to polynomial in x:
    # y^d = (1+x)^d
    inv = [0] * (E + 1)
    if E >= 1:
        inv[1] = 1
        for i in range(2, E + 1):
            inv[i] = P - (P // i) * inv[P % i] % P

    ans = [0] * (E + 1)
    for d, v in enumerate(F):
        if v == 0:
            continue
        c = 1
        ans[0] += v
        if ans[0] >= P:
            ans[0] -= P
        for m in range(d):
            c = c * (d - m) % P
            c = c * inv[m + 1] % P
            add = v * c % P
            ans[m + 1] += add
            if ans[m + 1] >= P:
                ans[m + 1] -= P

    print(*ans[N - 1:])

if __name__ == "__main__":
    main()

import sys

def matmul(a, b, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        row = res[i]
        ar = a[i]
        for k, x in enumerate(ar):
            if x:
                br = b[k]
                for j in range(n):
                    row[j] += x * br[j]
        for j in range(n):
            row[j] %= mod
    return res

def matpow(a, e, mod):
    n = len(a)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    base = a
    while e:
        if e & 1:
            res = matmul(res, base, mod)
        e >>= 1
        if e:
            base = matmul(base, base, mod)
    return res

def main():
    input = sys.stdin.readline
    n, p = map(int, input().split())
    a = [list(map(int, input().split())) for _ in range(n)]

    if p == 2:
        v = n & 1
        line = " ".join([str(v)] * n)
        print("\n".join([line] * n))
        return

    c = [[0] * n for _ in range(n)]
    zero_count = 0
    zero_loops = []
    zero_offdiag = []

    for i in range(n):
        for j in range(n):
            if a[i][j] == 0:
                zero_count += 1
                if i == j:
                    zero_loops.append(i)
                else:
                    zero_offdiag.append((i, j))
            else:
                c[i][j] = a[i][j] % p

    ans = matpow(c, p, p)

    # A zero diagonal edge can appear p-1 times, with the one fixed edge
    # placed before or after it.
    for u in zero_loops:
        for i in range(n):
            ans[i][u] += c[i][u]
        for j in range(n):
            ans[u][j] += c[u][j]

    # Only for p = 3 can a non-loop zero edge appear p-1 = 2 times.
    if p == 3:
        for u, v in zero_offdiag:
            ans[u][v] += c[v][u]

    negate = zero_count & 1
    out = []
    for i in range(n):
        row = []
        for x in ans[i]:
            x %= p
            if negate:
                x = (-x) % p
            row.append(str(x))
        out.append(" ".join(row))
    print("\n".join(out))

if __name__ == "__main__":
    main()

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, A, B = data[:4]
    intervals = []
    idx = 4
    for _ in range(M):
        L, R = data[idx], data[idx + 1]
        intervals.append((L, R))
        idx += 2

    if A == B:
        if (N - 1) % A != 0:
            print("No")
            return

        for L, R in intervals:
            k = (L - 1 + A - 1) // A
            p = 1 + k * A
            if p <= R:
                print("No")
                return

        print("Yes")
        return

    mask = (1 << B) - 1
    predecessor_mask = ((1 << B) - 1) ^ ((1 << (A - 1)) - 1)

    state = 1  # bit d means position current_position - d is reachable
    pos = 1

    def advance_good(state, length):
        if length <= 0:
            return state

        steps = min(length, 500)
        for _ in range(steps):
            nxt = 1 if (state & predecessor_mask) else 0
            state = ((state << 1) & mask) | nxt

        if length > 500:
            if state:
                state = mask

        return state

    def advance_bad(state, length):
        if length >= B:
            return 0
        return (state << length) & mask

    for L, R in intervals:
        state = advance_good(state, L - pos - 1)
        state = advance_bad(state, R - L + 1)
        pos = R

    state = advance_good(state, N - pos)

    print("Yes" if (state & 1) else "No")

if __name__ == "__main__":
    main()

from typing import List


class SegmentTreeBeats:
    INF = 10**30

    def __init__(self, n: int):
        self.n = n
        size = 4 * n + 5
        self.mn = [0] * size
        self.smn = [self.INF] * size
        self.mx = [0] * size
        self.lazy_add = [0] * size
        self._build(1, 0, n - 1)

    def _build(self, node: int, left: int, right: int) -> None:
        self.mn[node] = 0
        self.mx[node] = 0
        self.smn[node] = self.INF
        if left == right:
            return
        mid = (left + right) // 2
        self._build(node * 2, left, mid)
        self._build(node * 2 + 1, mid + 1, right)

    def _apply_add(self, node: int, value: int) -> None:
        self.mn[node] += value
        self.mx[node] += value
        if self.smn[node] != self.INF:
            self.smn[node] += value
        self.lazy_add[node] += value

    def _apply_chmax(self, node: int, value: int) -> None:
        if value <= self.mn[node]:
            return
        if self.mx[node] == self.mn[node]:
            self.mx[node] = value
        self.mn[node] = value

    def _push(self, node: int) -> None:
        add = self.lazy_add[node]
        if add:
            self._apply_add(node * 2, add)
            self._apply_add(node * 2 + 1, add)
            self.lazy_add[node] = 0

        floor = self.mn[node]
        if self.mn[node * 2] < floor:
            self._apply_chmax(node * 2, floor)
        if self.mn[node * 2 + 1] < floor:
            self._apply_chmax(node * 2 + 1, floor)

    def _pull(self, node: int) -> None:
        left = node * 2
        right = left + 1

        self.mx[node] = max(self.mx[left], self.mx[right])
        self.mn[node] = min(self.mn[left], self.mn[right])

        second = self.INF
        if self.mn[left] == self.mn[node]:
            second = min(second, self.smn[left])
        else:
            second = min(second, self.mn[left])

        if self.mn[right] == self.mn[node]:
            second = min(second, self.smn[right])
        else:
            second = min(second, self.mn[right])

        self.smn[node] = second

    def add_all(self, value: int) -> None:
        self._apply_add(1, value)

    def point_add(self, pos: int, value: int) -> None:
        self._point_add(1, 0, self.n - 1, pos, value)

    def _point_add(self, node: int, left: int, right: int, pos: int, value: int) -> None:
        if left == right:
            self._apply_add(node, value)
            return

        self._push(node)
        mid = (left + right) // 2
        if pos <= mid:
            self._point_add(node * 2, left, mid, pos, value)
        else:
            self._point_add(node * 2 + 1, mid + 1, right, pos, value)
        self._pull(node)

    def chmax_all(self, value: int) -> None:
        self._chmax(1, 0, self.n - 1, value)

    def _chmax(self, node: int, left: int, right: int, value: int) -> None:
        if value <= self.mn[node]:
            return
        if value < self.smn[node]:
            self._apply_chmax(node, value)
            return

        self._push(node)
        mid = (left + right) // 2
        self._chmax(node * 2, left, mid, value)
        self._chmax(node * 2 + 1, mid + 1, right, value)
        self._pull(node)

    def maximum(self) -> int:
        return self.mx[1]


class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        # Maximum subarray sum without deleting anything.
        best = current = nums[0]
        for value in nums[1:]:
            current = max(value, current + value)
            best = max(best, current)

        negatives = list({value for value in nums if value < 0})
        if not negatives:
            return best

        index = {value: i for i, value in enumerate(negatives)}
        tree = SegmentTreeBeats(len(negatives))

        # For each negative value x, maintain Kadane's DP value after
        # removing every occurrence of x.
        for value in nums:
            if value >= 0:
                tree.add_all(value)
            else:
                # Every deletion choice receives value, except deleting
                # this exact negative value, which should be skipped.
                tree.add_all(value)
                tree.point_add(index[value], -value)
                tree.chmax_all(0)

            best = max(best, tree.maximum())

        return best

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        fact = [1] * n
        for i in range(1, n):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * n
        inv_fact[n - 1] = pow(fact[n - 1], MOD - 2, MOD)
        for i in range(n - 1, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        combinations = fact[n - 1] * inv_fact[k] % MOD
        combinations = combinations * inv_fact[n - 1 - k] % MOD

        return combinations * m % MOD * pow(m - 1, n - 1 - k, MOD) % MOD

