from itertools import combinations

def main():
    input = sys.stdin.buffer.readline
    N, K = map(int, input().split())
    A = list(map(int, input().split()))

    total_xor = 0
    for x in A:
        total_xor ^= x

    if K == N:
        print(total_xor)
        return

    if K <= N - K:
        ans = 0
        for comb in combinations(A, K):
            x = 0
            for v in comb:
                x ^= v
            if x > ans:
                ans = x
    else:
        r = N - K
        ans = 0
        for comb in combinations(A, r):
            x = 0
            for v in comb:
                x ^= v
            value = total_xor ^ x
            if value > ans:
                ans = value

    print(ans)

