class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def can(limit: int) -> bool:
            if limit == 1:
                flips1 = sum(s[i] != str(i % 2) for i in range(n))
                flips2 = n - flips1
                return min(flips1, flips2) <= numOps

            operations = 0
            run_length = 1

            for i in range(1, n):
                if s[i] == s[i - 1]:
                    run_length += 1
                else:
                    operations += run_length // (limit + 1)
                    run_length = 1

            operations += run_length // (limit + 1)
            return operations <= numOps

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2
            if can(mid):
                right = mid
            else:
                left = mid + 1

        return left

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(threshold + 1))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        components = len(nums)
        representative = [0] * (threshold + 1)

        for x in nums:
            if x > threshold:
                continue

            for multiple in range(x, threshold + 1, x):
                if representative[multiple] == 0:
                    representative[multiple] = x
                else:
                    y = representative[multiple]
                    rx = find(x)
                    ry = find(y)
                    if rx != ry:
                        parent[rx] = ry
                        components -= 1

        return components
